import hashlib,json
from pathlib import Path
names=('workflow','boundary','duplicate_id','missing_prerequisite','overload','malformed')
root=Path('docs/evidence/runs'); data={}; unique={key:set() for key in ('attempt_id','artifact_id','observation_id','controller_birth','native_worker_birth')}; summary={}
for epoch in ('target','full'):
 rows=[]
 for name in names:
  path=root/('v1-07b-'+epoch+'-'+name+'.json'); raw=path.read_bytes(); run=json.loads(raw); data[epoch,name]=run
  for key,records in [('attempt_id',run['database']['execution_attempts']),('artifact_id',run['artifacts']),('observation_id',run['observations'])]:
   for record in records:
    value=record[key]; assert value not in unique[key]; unique[key].add(value)
  for call in run['calls']:
   meta=call['metadata'][0]; value=(meta['pid'],meta['start_ticks']); assert value not in unique['controller_birth']; unique['controller_birth'].add(value)
  for row in run['database']['execution_attempts']:
   worker=json.loads(row['binding_json'])['supervision']['worker']; value=(worker['pid'],worker['start_ticks']); assert value not in unique['native_worker_birth']; unique['native_worker_birth'].add(value)
  rows.append({'name':name,'sha256':hashlib.sha256(raw).hexdigest(),'native_actions':len(run['database']['execution_attempts']),'fresh_cli_calls':len(run['calls']),'outer_controller_wall_seconds':sum(c['wall_seconds'] for c in run['calls']),'successful_evaluator_body_cpu_seconds':sum(e['worker_cpu_seconds'] for e in run['result_envelopes'].values())})
 summary[epoch]=rows
for name in names:
 left,right=(data[e,name] for e in ('target','full'))
 facts=lambda run:sorted(json.dumps({key:o[key] for key in ('name','values','validation','protocol_fingerprint','comparison_scope')},sort_keys=True) for o in run['observations'])
 assert facts(left)==facts(right),name
 candidates=lambda run:sorted(a['content_sha256'] for a in run['artifacts'] if a['logical_name']=='candidate')
 assert candidates(left)==candidates(right),name
assert {key:len(value) for key,value in unique.items()}=={'attempt_id':34,'artifact_id':32,'observation_id':18,'controller_birth':44,'native_worker_birth':34}
print(json.dumps({'epochs':summary,'distinct_identity_counts':{key:len(value) for key,value in unique.items()},'same_candidate_bytes_and_scientific_facts':True,'accounting':'Each epoch independently contains 17 native actions, 34 reserved seconds and 22 fresh CLI calls. No additional worker was started by this read-only check.','timing_limit':'Observed epochs are not controlled efficiency comparisons; successful evaluator body CPU excludes producers, failed evaluator and final output write. No faster subset, overhead ratio or speedup claim.'},sort_keys=True))
